const input = $input.first().json;
const context = input.approval_action === 'browse' ? input : $('Prepare manual approval').first(0, -1).json;
const pageCount = Math.max(1, Math.ceil(context.approval_products.length / 10));
const page = context.approval_page ?? 0;
if (!Number.isSafeInteger(page) || page < 0 || page >= pageCount) throw new Error('Invalid approval catalog page.');
const revision = (context.approval_revision ?? -1) + 1;
const description = context.approval_base_description ?? context.approval_description;
return [{ json: { ...context, approval_page: page, approval_page_count: pageCount,
  approval_revision: revision, approval_context_key: `${context.import_key}:approval:${revision}`,
  approval_page_products: context.approval_products.slice(page * 10, (page + 1) * 10),
  approval_base_description: description,
  approval_description: `${description}<p>Catalog page ${page + 1} of ${pageCount}. To browse, choose Map to existing product and purchase, select Next catalog page or Previous catalog page, and submit without a conversion. Navigation never saves a mapping or adds stock; pages wrap at the ends. Unavailable slots are not product choices.</p>`,
}, pairedItem: { item: 0 } }];

function requiredString(value, field) {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`Mapping lookup requires a non-empty ${field}.`);
  }
  return value.trim();
}

function cents(value, field) {
  if ((typeof value !== 'number' && typeof value !== 'string')
      || !/^\d+$/.test(String(value))
      || !Number.isSafeInteger(Number(value))) {
    throw new Error(`${field} must be a non-negative, safe integer amount in cents.`);
  }
  return String(Number(value));
}

return $input.all().map((input, index) => {
  const row = input.json;
  if (row.review_required === true || (Array.isArray(row.parse_issues) && row.parse_issues.length)) {
    throw new Error(`Input ${index} has unresolved receipt parsing issues.`);
  }
  if (row.line_kind !== undefined && row.line_kind !== 'product') {
    throw new Error(`Input ${index} is not a stock product; route deposits and discounts separately.`);
  }

  const name = requiredString(row.product_name ?? row.name ?? row.normalized_description, 'product_name');
  const retailer = requiredString(row.retailer_key ?? 'edeka', 'retailer_key').toLowerCase();
  const unit = requiredString(row.receipt_unit, 'receipt_unit').toLowerCase();
  const quantity = String(row.receipt_quantity).replace(',', '.');
  if (!/^\d{1,12}(?:\.\d{1,6})?$/.test(quantity) || Number(quantity) <= 0) {
    throw new Error(`Input ${index}: receipt_quantity must be positive with at most six decimal places.`);
  }
  const total = cents(row.line_total_minor, 'line_total_minor');
  const netTotal = cents(row.net_line_total_minor ?? row.line_total_minor, 'net_line_total_minor');
  if (Number(netTotal) > Number(total)) {
    throw new Error(`Input ${index}: net_line_total_minor exceeds the printed product total.`);
  }

  return {
    json: {
      ...row,
      product_name: name,
      retailer_key: retailer,
      normalized_description: name.normalize('NFKC').replace(/\s+/g, ' ').trim().toLowerCase(),
      receipt_quantity: quantity,
      receipt_unit: unit,
      line_total_minor: total,
      net_line_total_minor: netTotal,
    },
    pairedItem: { item: index },
  };
});

return $input.all().map((input, index) => {
  const { receipt_item: receiptItem, mapping_candidates: candidates } = input.json;
  if (!receiptItem || typeof receiptItem !== 'object' || Array.isArray(receiptItem)
      || !Array.isArray(candidates)) {
    throw new Error('Unexpected PostgreSQL lookup response; expected receipt_item and mapping_candidates.');
  }

  const output = {
    ...receiptItem,
    mapping_candidates: candidates,
    mapping_candidate_count: candidates.length,
    mapping_status: candidates.length === 0 ? 'missing' : 'ambiguous',
    mapping_ready: false,
    review_required: true,
    mapping_reason: candidates.length === 0
      ? 'No confirmed mapping. Product search and manual approval are required.'
      : 'Multiple confirmed mappings. Review the candidates instead of choosing the first.',
  };

  if (candidates.length === 1) {
    const candidate = candidates[0];
    const ids = ['product_id', 'alias_id', 'grocy_product_id', 'grocy_stock_unit_id'];
    const positiveDecimals = ['conversion_factor', 'stock_quantity'];
    const valid = candidate && typeof candidate === 'object'
      && ids.every(field => /^[1-9]\d*$/.test(candidate[field]))
      && positiveDecimals.every(field =>
        /^\d+(?:\.\d+)?$/.test(candidate[field])
        && Number.isFinite(Number(candidate[field]))
        && Number(candidate[field]) > 0)
      && /^\d+(?:\.\d+)?$/.test(candidate.price_per_stock_unit)
      && Number.isFinite(Number(candidate.price_per_stock_unit));

    if (valid) {
      Object.assign(output, {
        product_id: candidate.product_id,
        alias_id: candidate.alias_id,
        barcode: candidate.barcode,
        mapped_product_name: candidate.product_name,
        grocy_product_id: candidate.grocy_product_id,
        grocy_stock_unit_id: candidate.grocy_stock_unit_id,
        conversion_factor: candidate.conversion_factor,
        stock_quantity: candidate.stock_quantity,
        price_per_stock_unit: candidate.price_per_stock_unit,
        mapping_status: 'matched',
        mapping_ready: true,
        review_required: false,
        mapping_reason: 'Exactly one confirmed mapping.',
      });
    } else {
      output.mapping_status = 'invalid_mapping';
      output.mapping_reason = 'The mapping contains invalid Grocy IDs, conversion factors or calculated amounts.';
    }
  }

  return { json: output, pairedItem: { item: index } };
});

function text(value, field) {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`Saving a mapping requires a non-empty ${field}.`);
  }
  return value.trim();
}

function id(value, field) {
  const normalized = String(value);
  if (!/^[1-9]\d{0,18}$/.test(normalized)
      || BigInt(normalized) > 9223372036854775807n
      || (typeof value === 'number' && !Number.isSafeInteger(value))) {
    throw new Error(`${field} must be a positive PostgreSQL BIGINT identifier.`);
  }
  return normalized;
}

function positiveDecimal(value, field) {
  const normalized = String(value).replace(',', '.');
  if (!/^\d{1,12}(?:\.\d{1,6})?$/.test(normalized) || Number(normalized) <= 0) {
    throw new Error(`${field} must be positive with at most six decimal places.`);
  }
  return normalized;
}

return $input.all().map((input, index) => {
  const row = input.json;
  if (row.mapping_confirmed !== true) {
    throw new Error('Mapping not approved. Set mapping_confirmed=true only after a trusted/manual approval step.');
  }
  const approved = row.approved_mapping;
  if (!approved || typeof approved !== 'object' || Array.isArray(approved)) {
    throw new Error('Expected an approved_mapping object from the approval step.');
  }
  const productId = approved.product_id == null ? null : id(approved.product_id, 'product_id');
  const barcode = approved.barcode == null ? null : text(approved.barcode, 'barcode');
  if (productId === null && barcode === null) {
    throw new Error('Supply an existing products.id or a barcode. Create barcode-free catalog products once before mapping them.');
  }
  if (barcode !== null && !/^\d{8,14}$/.test(barcode)) {
    throw new Error('barcode must be an 8-14 digit string; preserve leading zeroes.');
  }
  if (approved.barcode != null && typeof approved.barcode !== 'string') {
    throw new Error('barcode must be a string, not a number.');
  }

  const packageQuantity = approved.package_quantity == null
    ? null : positiveDecimal(approved.package_quantity, 'package_quantity');
  const packageUnit = approved.package_unit == null ? null : text(approved.package_unit, 'package_unit');
  if ((packageQuantity === null) !== (packageUnit === null)) {
    throw new Error('Provide both package_quantity and package_unit, or neither.');
  }
  if (approved.metadata != null
      && (typeof approved.metadata !== 'object' || Array.isArray(approved.metadata))) {
    throw new Error('metadata must be a JSON object when provided.');
  }

  return {
    json: {
      ...row,
      retailer_key: text(row.retailer_key, 'retailer_key').toLowerCase(),
      normalized_description: text(row.normalized_description, 'normalized_description')
        .normalize('NFKC').replace(/\s+/g, ' ').toLowerCase(),
      receipt_unit: text(row.receipt_unit, 'receipt_unit').toLowerCase(),
      approved_mapping: {
        product_id: productId,
        barcode,
        product_name: productId === null ? text(approved.product_name, 'product_name') : null,
        grocy_product_id: id(approved.grocy_product_id, 'grocy_product_id'),
        grocy_stock_unit_id: id(approved.grocy_stock_unit_id, 'grocy_stock_unit_id'),
        stock_units_per_receipt_unit: positiveDecimal(
          approved.stock_units_per_receipt_unit, 'stock_units_per_receipt_unit',
        ),
        package_quantity: packageQuantity,
        package_unit: packageUnit,
        metadata: approved.metadata ?? null,
      },
    },
    pairedItem: { item: index },
  };
});

return $input.all().map((input, index) => {
  const { receipt_item: receiptItem, saved_mapping: savedMapping } = input.json;
  if (!receiptItem || !savedMapping) {
    throw new Error('Mapping was not saved: the selected product does not exist or its barcode/product ID is already mapped to a different Grocy product.');
  }
  return {
    json: {
      ...receiptItem,
      cache_saved: true,
      saved_mapping: savedMapping,
    },
    pairedItem: { item: index },
  };
});

const itemPattern = /^(?:(?<quantity>\d+)[ \t]*\u20ac[ \t]*x[ \t]*(?<unit_price>\d+,\d{2})[ \t]*)?(?<name>.+?)[ \t]+(?<total>-?\d+,\d{2})[ \t]*\*?[ \t]*(?<code>AW|A|B)$/;
const weightPattern = /^kg[ \t]+x[ \t]*(?<quantity>\d+,\d+)[ \t]+(?<unit_price>\d+,\d{2})(?:[ \t]*\u20ac[ \t]*\/[ \t]*kg)?$/i;
const discountPattern = /^App[ \t]+Preis[ \t]*\/[ \t]*Rabatt[ \t]+(?<total>-?\d+,\d{2})(?:[ \t]*\*?[ \t]*(?<code>AW|A|B))?$/i;
const unitPattern = /^\u20ac[ \t]*\/[ \t]*kg$/i;

function toMinor(value) {
  const [whole, fraction] = value.replace(/^-/, '').split(',');
  const amount = Number(whole) * 100 + Number(fraction);
  if (!Number.isSafeInteger(amount)) {
    throw new Error(`Money amount exceeds the supported range: ${value}`);
  }
  return value.startsWith('-') ? -amount : amount;
}

return $input.all().map((input, inputIndex) => {
  const products = [];
  const adjustments = [];
  const parseIssues = [];
  let rawText = '';
  let pendingWeight = null;
  let previousProduct = null;

  function issue(code, lineNumber, rawLine, reason) {
    parseIssues.push({ code, line_number: lineNumber, raw_line: rawLine, reason });
  }

  function discardPendingWeight(reason) {
    if (pendingWeight) {
      issue('unattached_weight', pendingWeight.line_number, pendingWeight.raw_line, reason);
      pendingWeight = null;
    }
  }

  function result() {
    return {
      json: {
        ...input.json,
        retailer_key: 'edeka',
        receipt_input_index: inputIndex,
        rawText,
        products,
        adjustments,
        parse_issues: parseIssues,
        review_required: parseIssues.length > 0,
      },
      pairedItem: { item: inputIndex },
    };
  }

  const text = input.json?.text;
  if (typeof text !== 'string' || !text.trim()) {
    issue('missing_text', 0, '', 'Expected a non-empty $json.text from Extract from File.');
    return result();
  }

  const normalizedText = text.replace(/\r\n?/g, '\n').replace(/[\u00a0\u202f]/g, ' ');
  const start = /\bEUR\b/.exec(normalizedText);
  const end = /\bPosten[ \t]*:/i.exec(normalizedText);
  if (!start || !end || end.index <= start.index) {
    issue('receipt_boundaries', 0, '', 'Could not locate the item section between EUR and Posten:.');
    return result();
  }

  rawText = normalizedText.slice(start.index + start[0].length, end.index).trim();
  if (!rawText) {
    issue('empty_item_section', 0, '', 'The receipt item section is empty.');
    return result();
  }

  for (const [index, rawLine] of rawText.split('\n').entries()) {
    const lineNumber = index + 1;
    const line = rawLine.trim();
    if (!line) continue;

    if (/^-{3,}$/.test(line)) {
      discardPendingWeight('A separator was encountered before a product.');
      previousProduct = null;
      continue;
    }

    if (unitPattern.test(line)) {
      if (!previousProduct || previousProduct.receipt_unit !== 'kg' || pendingWeight) {
        issue('unattached_unit', lineNumber, line, 'The EUR/kg label has no preceding weighted product.');
      }
      continue;
    }

    const weight = line.match(weightPattern);
    if (weight) {
      discardPendingWeight('Another weight line was encountered before a product.');
      const quantity = Number(weight.groups.quantity.replace(',', '.'));
      if (!Number.isFinite(quantity) || quantity <= 0) {
        issue('invalid_quantity', lineNumber, line, 'Weight must be a positive finite number.');
      }
      pendingWeight = {
        quantity,
        unit_price_minor: toMinor(weight.groups.unit_price),
        line_number: lineNumber,
        raw_line: line,
      };
      previousProduct = null;
      continue;
    }

    const discount = line.match(discountPattern);
    if (discount) {
      discardPendingWeight('A discount was encountered before a product.');
      const amount = toMinor(discount.groups.total);
      adjustments.push({
        line_number: lineNumber,
        raw_description: line,
        line_kind: 'discount',
        line_total_minor: amount,
        receipt_code: discount.groups.code ?? null,
        applies_to_line_number: previousProduct?.line_number ?? null,
      });
      if (!previousProduct || amount >= 0) {
        issue('unresolved_discount', lineNumber, line, 'Expected a negative discount immediately after a product.');
      } else {
        previousProduct.discount_total_minor += amount;
        previousProduct.net_line_total_minor += amount;
        if (previousProduct.net_line_total_minor < 0) {
          issue('negative_net_total', lineNumber, line, 'Discounts exceed the preceding product total.');
        }
      }
      continue;
    }

    const match = line.match(itemPattern);
    if (!match) {
      discardPendingWeight('An unrecognized line was encountered before a product.');
      issue('unrecognized_line', lineNumber, line, 'This line needs a parsing rule or manual review.');
      previousProduct = null;
      continue;
    }

    const { name, quantity, unit_price: unitPrice, total, code } = match.groups;
    const isDeposit = /^(?:Pfand\b|Leerg)/i.test(name);
    if (pendingWeight && (quantity !== undefined || isDeposit)) {
      issue('conflicting_quantity', lineNumber, line, 'A weight cannot be combined with a counted item or deposit.');
    }

    const receiptQuantity = pendingWeight?.quantity ?? Number(quantity ?? 1);
    const receiptUnit = pendingWeight ? 'kg' : 'item';
    const lineTotal = toMinor(total);
    const unitPriceMinor = pendingWeight?.unit_price_minor
      ?? (unitPrice === undefined ? lineTotal : toMinor(unitPrice));

    if (!Number.isSafeInteger(receiptQuantity) && !pendingWeight) {
      issue('invalid_quantity', lineNumber, line, 'Item count exceeds the supported integer range.');
    }
    if (!Number.isFinite(receiptQuantity) || receiptQuantity <= 0) {
      issue('invalid_quantity', lineNumber, line, 'Quantity must be a positive finite number.');
    }
    const calculatedTotal = Math.round(receiptQuantity * unitPriceMinor);
    if (!Number.isSafeInteger(calculatedTotal) || Math.abs(calculatedTotal - lineTotal) > 1) {
      issue('price_mismatch', lineNumber, line, 'Quantity multiplied by unit price differs from the printed total by more than one cent.');
    }

    const row = {
      retailer_key: 'edeka',
      receipt_input_index: inputIndex,
      ...(input.json.source_key === undefined ? {} : { source_key: input.json.source_key }),
      line_number: lineNumber,
      raw_description: line,
      product_name: name.trim(),
      normalized_description: name.normalize('NFKC').trim().replace(/\s+/g, ' ').toLowerCase(),
      line_kind: isDeposit ? 'deposit' : 'product',
      receipt_quantity: receiptQuantity,
      receipt_unit: receiptUnit,
      unit_price_minor: unitPriceMinor,
      line_total_minor: lineTotal,
      receipt_code: code,
    };
    pendingWeight = null;

    if (isDeposit) {
      adjustments.push(row);
      previousProduct = null;
    } else {
      if (lineTotal < 0) {
        issue('negative_product_total', lineNumber, line, 'Negative product lines need a return/cancellation rule, not a stock addition.');
      }
      row.discount_total_minor = 0;
      row.net_line_total_minor = lineTotal;
      products.push(row);
      previousProduct = row;
    }
  }

  discardPendingWeight('The item section ended before a product.');
  if (!products.length && !adjustments.length) {
    issue('no_recognized_items', 0, '', 'No products or adjustments were recognized.');
  }
  return result();
});

return $input.all().flatMap((input, index) => {
  const { receipt_item: receipt, receipt_id: receiptId } = input.json;
  if (!receipt || !Array.isArray(receipt.products) || !/^[1-9]\d*$/.test(String(receiptId))
      || !/^[a-f0-9]{64}$/.test(receipt.receipt_fingerprint)) {
    throw new Error('Invalid registered receipt response.');
  }
  const sourceKey = `edeka:sha256:${receipt.receipt_fingerprint}`;
  return receipt.products.map(product => ({
    json: { ...product, receipt_id: String(receiptId), source_key: sourceKey,
      receipt_fingerprint: receipt.receipt_fingerprint,
      import_key: `${sourceKey}:line:${product.line_number}` },
    pairedItem: { item: index },
  }));
});

return $input.all().flatMap((input, index) => {
  const pdfs = Object.entries(input.binary ?? {}).filter(([, file]) =>
    file.mimeType?.toLowerCase() === 'application/pdf' || /\.pdf$/i.test(file.fileName ?? ''));
  if (!pdfs.length) throw new Error(`Message ${index} has no PDF receipt attachment.`);
  return pdfs.map(([key, file]) => ({
    json: { gmail_message_id: input.json.id, attachment_key: key, attachment_name: file.fileName ?? key },
    binary: { receipt_pdf: file },
    pairedItem: { item: index },
  }));
});

return $input.all().map((input, index) => ({
  json: { ...input.json, fingerprint_input: typeof input.json.text === 'string'
    ? input.json.text.normalize('NFKC').replace(/\s+/g, ' ').trim() : '' },
  pairedItem: { item: index },
}));

return $input.all().map((input, index) => {
  const { receipt_item: row, existing_import_status: status } = input.json;
  if (!row || !Object.hasOwn(input.json, 'existing_import_status')) {
    throw new Error('Invalid receipt line lookup response.');
  }
  const process = status === null;
  const review = !process && !['imported', 'skipped'].includes(status);
  return { json: { ...row, process_line: process, review_required: review,
    import_status: status,
    mapping_reason: review ? `Existing import is ${status}; reconcile the Grocy stock log before any retry.` : null },
    pairedItem: { item: index } };
});

const context = $('Load approval catalog').first(0, $runIndex).json;
if (!context.receipt_item || !Array.isArray(context.approval_products)) {
  throw new Error('Invalid approval catalog response.');
}
const response = $input.first().json;
const errors = Array.isArray(response.body?.errors) ? response.body.errors : [];
const searchOk = response.statusCode === 200 && Array.isArray(response.body?.hits)
  && response.body.timed_out !== true && errors.length === 0;
const candidates = searchOk ? response.body.hits.map(product => ({
  code: typeof product.code === 'string' && /^\d{8,14}$/.test(product.code) ? product.code : null,
  name: String(product.product_name ?? '').trim(),
  brands: Array.isArray(product.brands) ? product.brands.join(', ') : String(product.brands ?? ''),
  quantity: String(product.quantity ?? ''),
})) : [];
const suggestions = candidates.filter(product => product.code && product.name).map(product => ({
  ...product, option: `${product.code}: ${product.name} | ${product.brands} | ${product.quantity}`,
}));
const catalog = context.approval_products.filter(product =>
  /^[1-9]\d*$/.test(product.product_id) && /^[1-9]\d*$/.test(product.grocy_product_id)
  && /^[1-9]\d*$/.test(product.grocy_stock_unit_id));
const options = catalog.map(product => ({ ...product,
  option: `${product.product_id}: ${product.product_name} | barcode ${product.barcode ?? 'none'} | Grocy ${product.grocy_product_id} | stock unit ${product.grocy_stock_unit_id}`,
}));
const defaults = { location_id: 3, qu_id_stock: 3, qu_id_purchase: 3, default_best_before_days: 7 };
const escape = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[char]));
const row = context.receipt_item;
const searchError = errors.length
  ? errors.map(error => [error.title, error.description].filter(Boolean).join(': ')).join('; ')
  : response.body?.timed_out === true ? 'search timed out'
  : response.statusCode === 200 ? 'invalid response'
  : response.statusCode ?? response.error?.message ?? response.error ?? 'invalid response';
const searchNote = searchOk
  ? (candidates.length ? candidates.map(product => escape(`${product.name} ${product.brands} ${product.quantity} [${product.code ?? 'no barcode'}]`)).join('<br>') : 'No Open Food Facts candidates found.')
  : `Open Food Facts search failed (${escape(searchError)}). Select an existing product or ignore; nothing was automatically matched.`;
const catalogNote = catalog.length ? '' : '<p>No eligible existing products. Refresh the Grocy catalog to map an existing product, select an OFF suggestion to create one, or ignore.</p>';
return [{ json: { ...row, approval_products: options, approval_suggestions: suggestions,
  new_product_defaults: defaults, off_candidates: candidates,
  approval_description: `<p>${escape(row.product_name)}: ${escape(row.receipt_quantity)} ${escape(row.receipt_unit)}, EUR ${(Number(row.net_line_total_minor) / 100).toFixed(2)}.</p><p>Suggestions only:<br>${searchNote}</p>${catalogNote}<p>Choose an action and fill only its corresponding product selector. Mapping or creation requires the stock units per ONE receipt unit (${escape(row.receipt_unit)}); package size is not a conversion.</p><p>New products use Pantry (location ${defaults.location_id}), Pack (stock and purchase unit ${defaults.qu_id_stock}), and ${defaults.default_best_before_days} default best-before days. Approval saves the mapping and purchases this line. Ignore records a skipped line without stock changes.</p>`,
}, pairedItem: { item: 0 } }];

const context = $('Prepare approval page').first(0, -1).json;
const form = $input.first().json;
const { approval_products: catalog, approval_suggestions: suggestions, new_product_defaults: defaults,
  approval_page_products: pageProducts, approval_description, approval_base_description,
  approval_page, approval_page_count, approval_revision, approval_context_key, off_candidates, ...row } = context;
if (typeof form.receipt_line_key !== 'string' || form.receipt_line_key !== row.import_key
  || typeof form.approval_context_key !== 'string' || form.approval_context_key !== approval_context_key) {
  throw new Error('Stale or mismatched approval form. Open the latest approval link for this receipt line.');
}
if (form.Decision === 'Ignore this receipt line') {
  return [{ json: { ...row, approval_action: 'ignore', mapping_confirmed: false, review_required: false }, pairedItem: { item: 0 } }];
}
if (!['Map to existing product and purchase', 'Create from OFF suggestion and purchase'].includes(form.Decision)) {
  throw new Error('Explicit mapping, creation or ignore is required.');
}
if (form.Decision === 'Map to existing product and purchase'
  && ['Next catalog page', 'Previous catalog page'].includes(form['Catalog product'])) {
  const offset = form['Catalog product'] === 'Next catalog page' ? 1 : -1;
  return [{ json: { ...context, approval_action: 'browse', mapping_confirmed: false,
    approval_page: (approval_page + offset + approval_page_count) % approval_page_count,
  }, pairedItem: { item: 0 } }];
}
const factor = String(form['Stock units per receipt unit'] ?? '').trim().replace(',', '.');
if (!/^\d{1,12}(?:\.\d{1,6})?$/.test(factor) || Number(factor) <= 0) {
  throw new Error('Approval requires a positive stock-unit conversion with at most six decimal places.');
}
if (form.Decision === 'Map to existing product and purchase') {
  const selected = pageProducts.find(product => product.option === form['Catalog product']);
  if (!selected) throw new Error('Select an exact catalog product from the current page. Refresh the Grocy catalog if it is missing.');
  return [{ json: { ...row, approval_action: 'map', mapping_confirmed: true, review_required: false,
    approved_mapping: { product_id: selected.product_id, grocy_product_id: selected.grocy_product_id,
      grocy_stock_unit_id: selected.grocy_stock_unit_id, stock_units_per_receipt_unit: factor },
  }, pairedItem: { item: 0 } }];
}
const selected = suggestions.find(product => product.option === form['Open Food Facts suggestion']);
if (!selected) throw new Error('Select an Open Food Facts suggestion with a name and barcode to create a product.');
if (catalog.some(product => product.barcode === selected.code)) {
  throw new Error('This barcode already exists in the catalog. Map to the existing product instead.');
}
return [{ json: { ...row, approval_action: 'create', mapping_confirmed: false, review_required: false,
  new_product: { barcode: selected.code, name: selected.name, ...defaults,
    stock_units_per_receipt_unit: factor, brands: selected.brands, package_description: selected.quantity },
}, pairedItem: { item: 0 } }];

return $input.all().map((input, index) => {
  const { receipt_item: row, skipped, existing_import_status: status } = input.json;
  if (!row || typeof skipped !== 'boolean') throw new Error('Invalid skipped-line response.');
  const review = !skipped && status !== 'skipped';
  return { json: { ...row, review_required: review, import_status: skipped ? 'skipped' : status,
    mapping_reason: review ? `Skip was not recorded: another execution owns this line (${status ?? 'concurrent commit'}). Check Grocy before making any change.` : null,
  }, pairedItem: { item: index } };
});

const config = $input.first().json;
if (config.CURRENCY !== 'EUR') throw new Error('Grocy currency must be EUR before importing EUR receipt prices.');
return [{ json: { ...$('Confirmed mapping usable?').item.json }, pairedItem: { item: 0 } }];

const row = $('Verify Grocy currency').item.json;
const details = $input.first().json;
const product = details.product;
const stockQuantity = typeof row.stock_quantity === 'string'
  ? row.stock_quantity.replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '') : '';
let reason = null;
if (!product || String(product.id) !== row.grocy_product_id) {
  reason = 'Live Grocy product does not match the confirmed mapping.';
} else if (String(product.qu_id_stock) !== row.grocy_stock_unit_id
    || String(details.quantity_unit_stock?.id) !== row.grocy_stock_unit_id) {
  reason = 'Grocy stock unit has changed. Review the saved conversion before purchasing.';
} else if (String(product.enable_tare_weight_handling) !== '0') {
  reason = 'Tare-weight handling requires manual processing; receipt quantity is not gross container weight.';
} else if (!/^(?:-1|\d+)$/.test(String(product.default_best_before_days))
    || Number(product.default_best_before_days) > 365000) {
  reason = 'Grocy has an unsupported default best-before interval.';
} else if (!/^\d{1,12}(?:\.\d{1,6})?$/.test(stockQuantity)
    || Number(stockQuantity) <= 0 || !Number.isFinite(Number(row.price_per_stock_unit))) {
  reason = 'Calculated stock quantity or unit price is outside the supported range.';
}
if (reason) return [{ json: { ...row, purchase_ready: false, review_required: true, mapping_reason: reason }, pairedItem: { item: 0 } }];
const days = Number(product.default_best_before_days);
const bestBefore = days === -1 ? '2999-12-31' : $now.startOf('day').plus({ days }).toISODate();
return [{ json: { ...row, stock_quantity: stockQuantity, purchase_ready: true, review_required: false,
  purchase_body: { amount: stockQuantity, price: row.price_per_stock_unit,
    transaction_type: 'purchase', best_before_date: bestBefore, note: `Receipt import ${row.import_key}` },
}, pairedItem: { item: 0 } }];

return $input.all().map((input, index) => {
  const result = input.json;
  if (!result.receipt_item || typeof result.import_claimed !== 'boolean') throw new Error('Invalid import claim response.');
  if (result.import_claimed && !/^[1-9]\d*$/.test(result.receipt_line_id)) throw new Error('Claimed import has no receipt line ID.');
  const status = result.existing_import_status;
  return { json: { ...result.receipt_item, receipt_line_id: result.receipt_line_id,
    import_claimed: result.import_claimed, import_status: result.import_claimed ? 'sending' : status,
    review_required: !result.import_claimed && !['imported', 'skipped'].includes(status),
    mapping_reason: result.import_claimed ? null : `Import already claimed (${status ?? 'concurrent execution'}); check Grocy before retrying.`,
  }, pairedItem: { item: index } };
});

const row = $('Import claimed?').item.json;
const response = $input.first().json;
const valid = response.statusCode === 200 && Array.isArray(response.body) && response.body.length > 0
  && response.body.every(entry => entry && /^[1-9]\d*$/.test(String(entry.id))
    && String(entry.product_id) === row.grocy_product_id && entry.transaction_type === 'purchase');
return [{ json: { ...row, import_status: valid ? 'imported' : 'uncertain',
  grocy_response: response, review_required: !valid,
  mapping_reason: valid ? null : `Grocy purchase outcome is uncertain (${response.statusCode ?? 'transport error'}). Reconcile using stock note ${row.import_key}; do not retry automatically.`,
}, pairedItem: { item: 0 } }];

return $input.all().map((input, index) => {
  if (input.json.outcome_recorded !== true || !input.json.receipt_item) {
    throw new Error('Grocy was contacted but the import outcome was not recorded. Reconcile before any retry.');
  }
  return { json: input.json.receipt_item, pairedItem: { item: index } };
});

const row = $('Create new product?').item.json;
const response = $input.first().json;
const valid = response.statusCode === 200 && Array.isArray(response.body);
const ready = valid && response.body.length === 0;
return [{ json: { ...row, creation_ready: ready, review_required: !ready,
  mapping_reason: ready ? null : valid
    ? 'This barcode already exists in Grocy. Refresh the catalog and map to its existing product; nothing was created.'
    : 'Could not verify the barcode in Grocy. Nothing was created; check the request before retrying.',
  creation_body: { name: row.new_product.name,
    description: `Open Food Facts ${row.new_product.barcode}; ${row.new_product.brands}; ${row.new_product.package_description}`,
    location_id: row.new_product.location_id, qu_id_stock: row.new_product.qu_id_stock,
    qu_id_purchase: row.new_product.qu_id_purchase,
    default_best_before_days: row.new_product.default_best_before_days,
    min_stock_amount: 0, enable_tare_weight_handling: 0 },
}, pairedItem: { item: 0 } }];

const result = $input.first().json;
if (!result.receipt_item || typeof result.creation_claimed !== 'boolean') throw new Error('Invalid product creation claim response.');
return [{ json: { ...result.receipt_item, creation_claimed: result.creation_claimed,
  review_required: !result.creation_claimed,
  mapping_reason: result.creation_claimed ? null : result.existing_grocy_product_id
    ? 'This barcode is already in the catalog. Map to the existing product instead; nothing was created.'
    : `Barcode creation is already ${result.existing_creation_status ?? 'claimed by another execution'}. Reconcile Grocy and receipt_product_creations before any retry.`,
}, pairedItem: { item: 0 } }];

const row = $('Creation claimed?').item.json;
const response = $input.first().json;
const id = response.body?.created_object_id;
const valid = response.statusCode === 200 && (typeof id === 'string' || typeof id === 'number')
  && /^[1-9]\d{0,18}$/.test(String(id)) && BigInt(String(id)) <= 9223372036854775807n
  && (typeof id !== 'number' || Number.isSafeInteger(id));
return [{ json: { ...row, new_grocy_product_id: valid ? String(id) : null,
  creation_status: valid ? 'sending_barcode' : 'uncertain', creation_response: response,
  review_required: !valid, mapping_reason: valid ? null
    : `Product creation outcome is uncertain (${response.statusCode ?? 'transport error'}). Check Grocy and receipt_product_creations for barcode ${row.new_product.barcode}; do not retry automatically.`,
}, pairedItem: { item: 0 } }];

const result = $input.first().json;
if (result.outcome_recorded !== true || !result.receipt_item) {
  throw new Error('Grocy product creation was contacted but its outcome was not recorded. Reconcile before retrying.');
}
return [{ json: result.receipt_item, pairedItem: { item: 0 } }];

const row = $('Barcode registration ready?').item.json;
const response = $input.first().json;
const id = response.body?.created_object_id;
const valid = response.statusCode === 200 && (typeof id === 'string' || typeof id === 'number')
  && /^[1-9]\d{0,18}$/.test(String(id)) && BigInt(String(id)) <= 9223372036854775807n
  && (typeof id !== 'number' || Number.isSafeInteger(id));
return [{ json: { ...row, new_grocy_barcode_id: valid ? String(id) : null,
  creation_status: valid ? 'created' : 'uncertain', barcode_response: response,
  review_required: !valid, mapping_reason: valid ? null
    : `Barcode registration is uncertain for created Grocy product ${row.new_grocy_product_id}. Reconcile the product/barcode and creation log; do not create another product.`,
}, pairedItem: { item: 0 } }];

const result = $input.first().json;
if (!result.receipt_item || result.outcome_recorded !== true) {
  throw new Error('The created product/barcode outcome was not recorded. Reconcile Grocy and the creation log before retrying.');
}
const row = result.receipt_item;
if (result.recorded_creation_status !== 'created' || !/^[1-9]\d*$/.test(result.catalog_product_id)) {
  return [{ json: { ...row, mapping_confirmed: false, review_required: true,
    mapping_reason: result.creation_error ?? row.mapping_reason ?? 'Product registration is uncertain; reconcile before retrying.' },
    pairedItem: { item: 0 } }];
}
return [{ json: { ...row, approval_action: 'map', mapping_confirmed: true, review_required: false,
  approved_mapping: { product_id: result.catalog_product_id, grocy_product_id: row.new_grocy_product_id,
    grocy_stock_unit_id: String(row.new_product.qu_id_stock),
    stock_units_per_receipt_unit: row.new_product.stock_units_per_receipt_unit },
}, pairedItem: { item: 0 } }];
